import {mainQuery} from '@github-ui/react-core/future/main-query'
import {copilotInsightsUsageAppBuilder} from '../config/app-builder'
import type {CopilotUsageRouteResponse} from '@github-ui/copilot-insights-shared/types/copilot-usage-route-types'
export const periodMap: Record<string, string> = {
  '7d': '7 days',
  '14d': '14 days',
  '28d': '28 days',
}

// stafftools version of the route
export const stafftoolsCopilotUsageRoute = copilotInsightsUsageAppBuilder.createQueryRouteConfig(
  'stafftoolsCopilotUsageRoute',
  {
    path: '/stafftools/enterprises/:slug/copilot_insights_usage',
    queries: [
      mainQuery<CopilotUsageRouteResponse>({
        queryDeps: ({pathname, searchParams}) => ({
          pathname,
          searchParams: {
            period: searchParams.get('period') || '28d',
          },
        }),
      }),
    ],
  },
)

