import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {
  copilotUsageRoute,
  orgCopilotUsageRoute,
  stafftoolsCopilotUsageRoute,
  stafftoolsCopilotUsageSparkRoute,
  stafftoolsUserCopilotUsageRoute,
  stafftoolsUserCopilotUsageSparkRoute,
} from './copilot-usage-route'
import {clsx} from 'clsx'
import {useMatch} from '@github-ui/react-router'
import LineChart from '@github-ui/copilot-insights-shared/components/charts/LineChart'
import ColumnChart from '@github-ui/copilot-insights-shared/components/charts/ColumnChart'
import StackedAreaChart from '@github-ui/copilot-insights-shared/components/charts/StackedAreaChart'
import {
  blueShades,
  greenShades,
  orangeShades,
} from '@github-ui/copilot-insights-shared/components/charts/utils/chart-colors'
import {CopilotBlankslate} from '@github-ui/copilot-insights-shared/components/CopilotBlankslate'
import {Header} from '@github-ui/copilot-insights-shared/components/header/Header'
import MetricCards from '@github-ui/copilot-insights-shared/components/metric-cards/MetricCards'
import DataDisclaimer from '@github-ui/copilot-insights-shared/components/header/DataDisclaimer'
import {useQuerySanitizer} from '@github-ui/copilot-insights-shared/hooks/useQuerySanitizer'
import DataCard from '@github-ui/data-card'
import {Flash, Stack} from '@primer/react'
import MultipleSeriesLineChart from '@github-ui/copilot-insights-shared/components/charts/MultipleSeriesLineChart'
import DonutChart from '@github-ui/copilot-insights-shared/components/charts/DonutChart'
import AreaChart from '@github-ui/copilot-insights-shared/components/charts/AreaChart'
import styles from '../styles.module.css'
import {InsightsSidenavPanel} from '@github-ui/insights-sidenav'

type CopilotUsageRouteType =
  | typeof orgCopilotUsageRoute
  | typeof copilotUsageRoute
  | typeof orgCopilotUsageRoute
  | typeof stafftoolsCopilotUsageRoute
  | typeof stafftoolsCopilotUsageSparkRoute
  | typeof stafftoolsUserCopilotUsageRoute
  | typeof stafftoolsUserCopilotUsageSparkRoute

export function CopilotUsage() {
  const orgMatch = useMatch(orgCopilotUsageRoute.path)
  const stafftoolsMatch = useMatch(stafftoolsCopilotUsageRoute.path)
  const stafftoolsSparkMatch = useMatch(stafftoolsCopilotUsageSparkRoute.path)
  const stafftoolsUserMatch = useMatch(stafftoolsUserCopilotUsageRoute.path)
  const stafftoolsUserSparkMatch = useMatch(stafftoolsUserCopilotUsageSparkRoute.path)
  let routeToUse: CopilotUsageRouteType = copilotUsageRoute
  if (orgMatch) {
    routeToUse = orgCopilotUsageRoute
  } else if (stafftoolsMatch) {
    routeToUse = stafftoolsCopilotUsageRoute
  } else if (stafftoolsSparkMatch) {
    routeToUse = stafftoolsCopilotUsageSparkRoute
  } else if (stafftoolsUserMatch) {
    routeToUse = stafftoolsUserCopilotUsageRoute
  } else if (stafftoolsUserSparkMatch) {
    routeToUse = stafftoolsUserCopilotUsageSparkRoute
  }

  const payload = useRouteQuery(routeToUse, 'mainQuery')
  const {
    copilotLicenseManagementLink,
    aiControlsLink,
    exportFilesUrl,
    slug,
    businessId,
    orgId,
    canonicalQueryParams,
    usageMetrics,
    displayBlankslate,
    displayError,
    displayNoMatchingResults,
    importedDataFilename,
    displayUsageDisclaimer,
    insightsOptedIn,
    canManageAiControls,
    copilotDisabled,
    canManageCopilotLicenses,
    sidenav,
  } = payload?.data ?? {}

  const isOrgRoute =
    routeToUse === orgCopilotUsageRoute ||
    routeToUse === stafftoolsUserCopilotUsageRoute ||
    routeToUse === stafftoolsUserCopilotUsageSparkRoute
  const isEnterprise = !isOrgRoute && !sidenav

  useQuerySanitizer(canonicalQueryParams)

  const dailyActiveUserValues = usageMetrics?.dailyActiveUsers?.data?.map(d => d.value) ?? []
  const weeklyActiveUserValues = usageMetrics?.weeklyActiveUsers?.data?.map(d => d.value) ?? []
  const sharedMax = Math.max(0, ...dailyActiveUserValues, ...weeklyActiveUserValues)

  const renderCopilotUsageCharts = () => {
    if (copilotDisabled) {
      return (
        <CopilotBlankslate
          type="welcome"
          dashboardType="usage"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-usage-metrics-blankslate"
          copilotDisabled={copilotDisabled}
          canManageCopilotLicenses={canManageCopilotLicenses}
        />
      )
    } else if (insightsOptedIn === false) {
      return (
        <CopilotBlankslate
          type="policy-disabled"
          dashboardType="usage"
          aiControlsLink={`${aiControlsLink}#metrics`}
          testId="copilot-usage-metrics-policy-disabled"
          canManageAiControls={canManageAiControls}
          canManageCopilotLicenses={canManageCopilotLicenses}
          isEnterprise={isEnterprise}
        />
      )
    } else if (displayBlankslate || !usageMetrics) {
      return (
        <CopilotBlankslate
          type="welcome"
          dashboardType="usage"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-usage-metrics-blankslate"
          canManageCopilotLicenses={canManageCopilotLicenses}
          isEnterprise={isEnterprise}
        />
      )
    } else if (displayError) {
      return (
        <CopilotBlankslate
          type="error"
          dashboardType="usage"
          copilotLicenseManagementLink={copilotLicenseManagementLink}
          testId="copilot-usage-metrics-error"
          canManageCopilotLicenses={canManageCopilotLicenses}
          isEnterprise={isEnterprise}
        />
      )
    } else if (displayNoMatchingResults) {
      // When policy is enabled and metrics exist but timeframe has no data
      return (
        <CopilotBlankslate
          type="no-matching-results"
          dashboardType="usage"
          testId="copilot-usage-metrics-no-matching-results"
          isEnterprise={isEnterprise}
        />
      )
    }

    const metricCardsData = usageMetrics.metricCardsData.data

    return (
      <div className="flex-xl-row flex-column width-xl-auto width-full">
        <Stack direction="horizontal" wrap="wrap" className="gap-3">
          <Stack.Item grow>
            <MetricCards
              cards={[
                {
                  title: 'IDE active users',
                  value: metricCardsData.activeUsersCardData.totalActiveUsers,
                  description: 'Copilot-licensed users who interacted with Copilot in the current calendar month',
                  linkLabel: 'Manage licenses',
                  linkUrl: copilotLicenseManagementLink,
                },
                {
                  title: 'Agent adoption',
                  value: (
                    <Stack direction="horizontal" justify="space-between" align="baseline" className="mb-0">
                      <span className="f2">{metricCardsData.agentAdoptionCardData.rate}%</span>
                      <span className="color-fg-muted f6 text-right">
                        {metricCardsData.agentAdoptionCardData.usersTriedAgent} out of{' '}
                        {metricCardsData.agentAdoptionCardData.totalUsers} active users
                      </span>
                    </Stack>
                  ),
                  description: 'Active users who used any agent feature in the current calendar month',
                  children: (
                    <DataCard.ProgressBar
                      aria-valuenow={metricCardsData.agentAdoptionCardData.rate}
                      barSize="small"
                      style={{margin: '2px 0'}}
                      data={[
                        {
                          progress: metricCardsData.agentAdoptionCardData.rate,
                          color: 'var(--bgColor-accent-emphasis)',
                          label: 'Percent of agent adoption',
                        },
                      ]}
                    />
                  ),
                },
                {
                  title: 'Most used chat model',
                  value: metricCardsData.modelCardData.modelName,
                  description: 'Model with the highest number of chat requests in the last 28 days',
                },
              ]}
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <div className="d-flex flex-column flex-xl-row gap-3 width-full flex-xl-items-stretch">
              <div className="flex-1 min-width-0 d-flex flex-column">
                <AreaChart
                  payload={usageMetrics.dailyActiveUsers}
                  title="IDE daily active users"
                  description="Unique users who used Copilot on a given day, either via chat or code completions"
                  yAxisTitle="Users"
                  yAxisMax={sharedMax}
                />
              </div>
              <div className="flex-1 min-width-0 d-flex flex-column">
                <AreaChart
                  payload={usageMetrics.weeklyActiveUsers}
                  title="IDE weekly active users"
                  description="Unique users who used Copilot on a given week, either via chat or code completions"
                  yAxisTitle="Users"
                  yAxisMax={sharedMax}
                />
              </div>
            </div>
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <LineChart
              payload={usageMetrics.averageRequestsPerActiveChatUser}
              title="Average chat requests per active user"
              description="User-initiated requests across all chat modes, excluding code completions"
              yAxisTitle="Requests"
              chartWidth="auto"
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <ColumnChart
              payload={usageMetrics.requestsPerFeature}
              title="Requests per chat mode"
              description="User-initiated chat requests across all modes"
              yAxisTitle="Requests"
              columnColours={greenShades}
              chartWidth="full"
              stacked
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <div className="d-flex flex-column flex-xl-row gap-3 width-full flex-xl-items-stretch">
              <div className="flex-1 min-width-0 d-flex flex-column">
                <MultipleSeriesLineChart
                  payload={usageMetrics.codeCompletions}
                  title="Code completions"
                  description="Inline code suggestions shown and accepted"
                  yAxisTitle="Completions"
                  chartWidth="half"
                />
              </div>
              <div className="flex-1 min-width-0 d-flex flex-column">
                <LineChart
                  payload={usageMetrics.codeCompletionsAcceptanceRate}
                  title="Code completions acceptance rate"
                  description="Percentage of shown inline completions that were either fully or partially accepted"
                  yAxisTitle="%"
                  chartWidth="half"
                />
              </div>
            </div>
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <StackedAreaChart
              payload={usageMetrics.modelUsagePerDay}
              title="Model usage per day"
              description="Daily breakdown of models used in requests across all chat modes, excluding code completions"
              yAxisTitle="%"
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <div className="d-flex flex-column flex-xl-row gap-3 width-full flex-xl-items-stretch">
              <div className="flex-1 min-width-0 d-flex flex-column">
                <DonutChart
                  payload={usageMetrics.modelUsage.data}
                  title="Chat model usage"
                  description="Distribution of models used across all chat modes"
                  colors={blueShades}
                />
              </div>
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={usageMetrics.modelUsagePerFeature}
                  title="Model usage per chat mode"
                  description="Most frequently used models for user-initiated chat requests"
                  yAxisTitle="%"
                  columnColours={blueShades}
                  yAxisOptions={{tickAmount: 5}}
                  stacked
                />
              </div>
            </div>
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <StackedAreaChart
              payload={usageMetrics.languageUsagePerDay}
              title="Language usage per day"
              description="Daily breakdown of language usage in requests across all chat modes and code completions"
              yAxisTitle="%"
            />
          </Stack.Item>
          <Stack.Item grow className="width-full">
            <div className="d-flex flex-column flex-xl-row gap-3 width-full flex-xl-items-stretch">
              <div className="flex-1 min-width-0 d-flex flex-column">
                <DonutChart
                  payload={usageMetrics.languageUsage.data}
                  title="Language usage"
                  description="Distribution of languages used across all chat modes and code completions"
                  colors={orangeShades}
                />
              </div>
              <div className="flex-1 min-width-0 d-flex flex-column">
                <ColumnChart
                  payload={usageMetrics.modelUsagePerLanguage}
                  title="Model usage per language"
                  description="Most frequently used model in each language for user-initiated chat requests"
                  yAxisTitle="%"
                  columnColours={orangeShades}
                  yAxisOptions={{tickAmount: 5}}
                  stacked
                />
              </div>
            </div>
          </Stack.Item>
        </Stack>
      </div>
    )
  }

  const mainContent = (
    <div data-testid="copilot-usage-page" className="d-flex flex-column gap-3 overflow-x-hidden">
      <hr className={clsx('d-md-none mt-0 mb-0', styles.CopilotUsagePageDivider)} />
      {displayUsageDisclaimer && <DataDisclaimer testId="copilot-usage-disclaimer" />}
      <Header
        title={'Copilot IDE usage'}
        slug={slug}
        businessId={businessId}
        orgId={orgId}
        exportFilesUrl={exportFilesUrl}
        disableControls={displayBlankslate || displayError || insightsOptedIn === false}
        page="usage"
        isEnterprise={isEnterprise}
      />
      {importedDataFilename && (
        <Flash variant="warning" aria-live="polite" data-testid="imported-data-notice" className="mb-2">
          Displaying data from file: <strong>{importedDataFilename}</strong>
        </Flash>
      )}
      {renderCopilotUsageCharts()}
    </div>
  )

  // For org routes, wrap content with sidenav layout
  if (!isEnterprise && sidenav) {
    return (
      <div data-testid="copilot-usage-with-sidenav" className="d-flex flex-column flex-lg-row flex-content-stretch">
        <InsightsSidenavPanel
          selectedKey="copilot_metrics_usage"
          showDependencies={sidenav.showDependencies}
          showActionsUsageMetrics={sidenav.showActionsUsageMetrics}
          showApi={sidenav.showApi}
          showCopilotUsage={sidenav.showCopilotUsage}
          showCopilotCodeGeneration={sidenav.showCopilotCodeGeneration}
          urls={sidenav.urls}
        />
        <div className="flex-1 mx-lg-auto tmp-p-4" style={{maxWidth: 1664}}>
          {mainContent}
        </div>
      </div>
    )
  }

  return mainContent
}
